@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Uji {
}

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface SebelumSetiap {
}

class Periksa {
    static void sama(Object harapan, Object hasil) {
        if (!Objects.equals(harapan, hasil)) {
            throw new AssertionError("harapan " + harapan + " tetapi " + hasil);
        }
    }
}

class MiniUji {
    static void jalankan(Class<?> kelas) throws Exception {
        List<Method> uji = new ArrayList<>();
        Method sebelum = null;
        for (Method m : kelas.getDeclaredMethods()) {
            if (m.isAnnotationPresent(Uji.class)) {
                uji.add(m);
            }
            if (m.isAnnotationPresent(SebelumSetiap.class)) {
                sebelum = m;
            }
        }
        uji.sort(Comparator.comparing(Method::getName));
        int lulus = 0;
        for (Method m : uji) {
            Object objek = kelas.getDeclaredConstructor().newInstance();
            if (sebelum != null) {
                sebelum.invoke(objek);
            }
            try {
                m.invoke(objek);
                System.out.println("LULUS " + m.getName());
                lulus++;
            } catch (InvocationTargetException e) {
                System.out.println("GAGAL " + m.getName() + ": " + e.getCause().getMessage());
            }
        }
        System.out.println(lulus + " dari " + uji.size() + " lulus");
    }
}

